package cl.bolsillo.app;
import android.app.*;import android.content.*;import android.speech.RecognizerIntent;import android.widget.*;import org.json.*;import java.util.*;import java.util.regex.*;
final class VoiceEntry {
 static void listen(MainActivity a){try{Intent voice=new Intent(RecognizerIntent.ACTION_RECOGNIZE_SPEECH).putExtra(RecognizerIntent.EXTRA_LANGUAGE_MODEL,RecognizerIntent.LANGUAGE_MODEL_FREE_FORM).putExtra(RecognizerIntent.EXTRA_LANGUAGE,"es-CL").putExtra(RecognizerIntent.EXTRA_PROMPT,"Por ejemplo: gasté 2500 en café con MACH");a.startActivityForResult(voice,42);}catch(android.content.ActivityNotFoundException e){input(a,"");}}
 static void input(MainActivity a,String value){LinearLayout box=NativeSettings.panel(a,"Dictar movimiento");EditText phrase=NativeSettings.input(a,box,"Gasté 2500 en café con MACH",value);phrase.setSingleLine(false);Dialog dialog=NativeSettings.display(a,box);NativeSettings.action(a,box,"Usar micrófono",()->{dialog.dismiss();listen(a);});NativeSettings.action(a,box,"Revisar movimiento",()->a.attempt(()->{prepare(a,phrase.getText().toString());dialog.dismiss();}));NativeSettings.action(a,box,"Cancelar",dialog::dismiss);}
 static void prepare(MainActivity a,String spoken)throws Exception{String text=BankNotificationParser.normalize(spoken);boolean income=Pattern.compile("\\b(recibi|recibiste|ingreso|depositaron|deposito|me transfirieron|me pagaron|abono)\\b").matcher(text).find(),expense=Pattern.compile("\\b(gaste|gasto|pague|pago|compre|compra|cobro)\\b").matcher(text).find();Ledger.require(income!=expense,"Di si es gasto o ingreso");Matcher amount=Pattern.compile("(?:\\$\\s*)?([0-9]{1,3}(?:[., ][0-9]{3})+|[0-9]+)").matcher(spoken);Ledger.require(amount.find(),"Di un monto en pesos");long value=Long.parseLong(amount.group(1).replaceAll("[., ]",""));Ledger.require(value>0&&value<=Ledger.MAX,"Monto inválido");String account=text.contains("mach")?"bank-mach":text.contains("bancoestado")||text.contains("banco estado")?"bank-bancoestado":"";String note=spoken.replaceFirst("(?i)^.*?(?:\\$\\s*)?[0-9][0-9., ]*\\s*(?:en|para|por)\\s*"," ").trim();if(note.isEmpty()||note.equals(spoken))note=income?"Ingreso dictado":"Gasto dictado";if(note.length()>100)note=note.substring(0,100);final String name=note,kind=income?"income":"expense";if(account.isEmpty()){NativeSettings.chooseAccount(a,false,id->a.attempt(()->form(a,kind,id,value,name)));}else form(a,kind,account,value,name);}
 static void form(MainActivity a,String kind,String account,long amount,String name)throws Exception{Ledger.require(Ledger.find(a.data.getJSONArray("accounts"),account)!=null,"Cuenta no disponible");String category=kind.equals("income")?Detection.incomeCategory(a.data):Detection.category(a,a.data,name);JSONObject draft=NativeSync.transaction(kind,amount,account,"",category,name,"voice","");Forms.transaction(a,draft,kind);}
}
